  $('#version').innerHTML = `Test Directory <a href="${esc(TDX.meta.xlsxUrl)}">${esc(TDX.meta.directory)}</a>, eligibility criteria
    <a href="${esc(TDX.meta.pdfUrl)}">${esc(TDX.meta.criteria)}</a>${PANELS_DATE ? `, PanelApp ${esc(PANELS_DATE)}` : ''}.`;
  $('#filter-fields').innerHTML = FILTER_KEYS.map(k => { const f = FILTERS[k]; return `<label>${f.label}
    <select id="f-${k}" data-filter="${k}"><option value="">All</option>${f.values.map(v => `<option value="${esc(v)}">${esc((f.show || String)(v))}</option>`).join('')}</select></label>`; }).join('');
  // On a phone the filters start folded away (unless one is on), so the results show without scrolling.
